-- Disposable local database only. Never run against a hosted project.
BEGIN;
SELECT test.ensure((SELECT used=42 FROM rotamapa_private.google_usage WHERE bucket='migration-preserved' AND period='2000-01-01'),'migration preserves prior counters');
CREATE TEMP TABLE google_clients_before AS SELECT coalesce(jsonb_agg(to_jsonb(c) ORDER BY id),'[]'::jsonb) AS snapshot FROM public.clients c;
DELETE FROM rotamapa_private.google_usage;
DELETE FROM rotamapa_private.insider_memberships;
DELETE FROM rotamapa_private.qa_accounts;
DELETE FROM rotamapa_private.qa_operators;
INSERT INTO auth.users(id) SELECT ('00000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid FROM generate_series(1,8) n ON CONFLICT DO NOTHING;
UPDATE auth.users SET raw_app_meta_data='{}' WHERE id::text LIKE '00000000-0000-4000-8000-%';
INSERT INTO rotamapa_private.insider_memberships(slot,user_id) SELECT n,('00000000-0000-4000-8000-'||lpad((n+1)::text,12,'0'))::uuid FROM generate_series(1,4) n;
UPDATE auth.users SET raw_app_meta_data='{"rotamapa_membership":"signature_founder"}' WHERE id IN ('00000000-0000-4000-8000-000000000007','00000000-0000-4000-8000-000000000008');
INSERT INTO public.traxelo_plan_grants(user_id,plan,expires_at) SELECT id,'pro',NULL FROM auth.users WHERE id IN ('00000000-0000-4000-8000-000000000007','00000000-0000-4000-8000-000000000008') ON CONFLICT(user_id) DO UPDATE SET plan='pro',expires_at=NULL;
INSERT INTO public.rotamapa_portfolios(user_id,id,name) SELECT id,'00000000-0000-4000-8000-000000000000','Synthetic quota test' FROM auth.users ON CONFLICT DO NOTHING;
INSERT INTO public.rotamapa_portfolios(user_id,id,name) VALUES('00000000-0000-4000-8000-000000000002','00000000-0000-4000-8000-000000000199','Other synthetic portfolio') ON CONFLICT DO NOTHING;
UPDATE auth.users SET raw_user_meta_data='{"rotamapa_membership":"signature_founder","signature":true}' WHERE id='00000000-0000-4000-8000-000000000002';
SELECT set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000002',false);
SELECT set_config('request.jwt.claims','{"user_metadata":{"signature":true}}',false);
SELECT set_config('request.headers','{"x-rotamapa-portfolio":"00000000-0000-4000-8000-000000000000"}',false);
SET ROLE authenticated;
DO $$DECLARE r jsonb;BEGIN
 FOR i IN 1..20 LOOP r:=public.rotamapa_google_reserve_status();PERFORM test.ensure(r='{"allowed":true}', 'first twenty insider reservations allowed without counter disclosure');END LOOP;
 r:=public.rotamapa_google_reserve_status();
 PERFORM test.ensure(r->>'code'='google_user_daily_limit','twenty-first insider reservation blocked despite forged user metadata');
 PERFORM test.ensure((r->>'resetAt')::timestamptz=((timezone('America/Fortaleza',now())::date+1)::timestamp AT TIME ZONE 'America/Fortaleza'),'daily reset is next midnight in Fortaleza');
 PERFORM test.ensure(NOT(r ? 'used' OR r ? 'limit' OR r ? 'remaining'),'limits are not exposed');
 PERFORM test.ensure(NOT public.rotamapa_google_reserve(),'legacy boolean wrapper enforces same daily counter');
 BEGIN PERFORM used FROM rotamapa_private.google_usage;RAISE EXCEPTION 'private counters exposed';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
END$$;
SELECT set_config('request.headers','{"x-rotamapa-portfolio":"00000000-0000-4000-8000-000000000199"}',false);
SELECT test.ensure(public.rotamapa_google_reserve_status()->>'code'='google_user_daily_limit','switching portfolio does not reset daily cap');
RESET ROLE;
SELECT test.ensure((SELECT used=20 FROM rotamapa_private.google_usage WHERE bucket='project-month' AND period=date_trunc('month',timezone('America/Fortaleza',now()))::date),'denials do not increment project counter');
SELECT set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000003',false);
SELECT set_config('request.headers','{"x-rotamapa-portfolio":"00000000-0000-4000-8000-000000000000"}',false);
SET ROLE authenticated;
SELECT test.ensure((public.rotamapa_google_reserve_status()->>'allowed')::boolean,'another insider has independent daily allowance');
RESET ROLE;
UPDATE rotamapa_private.google_usage SET period=period-1 WHERE bucket='user:00000000-0000-4000-8000-000000000002' AND period=timezone('America/Fortaleza',now())::date;
SELECT set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000002',false);
SET ROLE authenticated;
SELECT test.ensure((public.rotamapa_google_reserve_status()->>'allowed')::boolean,'new day gets a fresh allowance without clearing history');
RESET ROLE;
SELECT test.ensure((SELECT used=20 FROM rotamapa_private.google_usage WHERE bucket='user:00000000-0000-4000-8000-000000000002' AND period=timezone('America/Fortaleza',now())::date-1),'prior-day count preserved');
-- Both Signature accounts remain unrestricted individually, including above old daily caps.
UPDATE rotamapa_private.google_usage SET used=3000 WHERE bucket='project-day' AND period=timezone('America/Fortaleza',now())::date;
UPDATE rotamapa_private.google_usage SET used=100 WHERE bucket='project-month' AND period=date_trunc('month',timezone('America/Fortaleza',now()))::date;
INSERT INTO rotamapa_private.google_usage(bucket,period,used) VALUES('user:00000000-0000-4000-8000-000000000007',timezone('America/Fortaleza',now())::date,4000),('user:00000000-0000-4000-8000-000000000008',timezone('America/Fortaleza',now())::date,4000);
SELECT set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000007',false);
SET ROLE authenticated;
SELECT test.ensure((public.rotamapa_google_reserve_status()->>'allowed')::boolean,'first Signature has no individual or daily project cap');
RESET ROLE;
SELECT set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000008',false);
SET ROLE authenticated;
SELECT test.ensure(public.rotamapa_google_reserve(),'second Signature legacy caller has no individual cap');
RESET ROLE;
UPDATE rotamapa_private.google_usage SET used=3999 WHERE bucket='project-month' AND period=date_trunc('month',timezone('America/Fortaleza',now()))::date;
SET ROLE authenticated;
SELECT test.ensure((public.rotamapa_google_reserve_status()->>'allowed')::boolean,'four-thousandth project reservation allowed');
SELECT test.ensure(public.rotamapa_google_reserve_status()->>'code'='google_project_monthly_limit','Signature remains subject to shared monthly ceiling');
RESET ROLE;
UPDATE rotamapa_private.google_usage SET used=20 WHERE bucket='user:00000000-0000-4000-8000-000000000002' AND period=timezone('America/Fortaleza',now())::date;
SELECT set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000002',false);
SET ROLE authenticated;
DO $$DECLARE r jsonb;BEGIN r:=public.rotamapa_google_reserve_status();PERFORM test.ensure(r->>'code'='google_project_monthly_limit','month wins over daily block');PERFORM test.ensure((r->>'resetAt')::timestamptz=((date_trunc('month',timezone('America/Fortaleza',now()))+interval '1 month') AT TIME ZONE 'America/Fortaleza'),'monthly reset is next month, not tomorrow');END$$;
RESET ROLE;
SELECT test.ensure((SELECT used=4000 FROM rotamapa_private.google_usage WHERE bucket='project-month' AND period=date_trunc('month',timezone('America/Fortaleza',now()))::date),'shared counter never exceeds ceiling');
UPDATE rotamapa_private.google_usage SET period=(period-interval '1 month')::date WHERE bucket='project-month' AND period=date_trunc('month',timezone('America/Fortaleza',now()))::date;
SELECT set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000007',false);
SET ROLE authenticated;
SELECT test.ensure((public.rotamapa_google_reserve_status()->>'allowed')::boolean,'new month gets fresh shared allowance');
RESET ROLE;
SELECT test.ensure((SELECT used=4000 FROM rotamapa_private.google_usage WHERE bucket='project-month' AND period=(date_trunc('month',timezone('America/Fortaleza',now()))-interval '1 month')::date),'prior-month count preserved');
SELECT set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000001',false);
SET ROLE authenticated;
DO $$BEGIN BEGIN PERFORM public.rotamapa_google_reserve_status();RAISE EXCEPTION 'nonmember consumed quota';EXCEPTION WHEN insufficient_privilege THEN NULL;END;END$$;
RESET ROLE;
SET ROLE anon;
DO $$BEGIN BEGIN PERFORM public.rotamapa_google_reserve_status();RAISE EXCEPTION 'anonymous execution granted';EXCEPTION WHEN insufficient_privilege THEN NULL;END;END$$;
RESET ROLE;
SELECT test.ensure((SELECT coalesce(jsonb_agg(to_jsonb(c) ORDER BY id),'[]'::jsonb) FROM public.clients c)=(SELECT snapshot FROM google_clients_before),'client data and pins untouched');
ROLLBACK;
SELECT 'Profile quota assertions passed' AS result;
